# Step 1: List all open tickets, paginating through all pages
first_page = list_tickets({ status: "open", page: 1 })
all_items = first_page.items

remaining_items = for page in list.range(2, first_page.total_pages + 1) {
    result = list_tickets({ status: "open", page })
    return result.items
}

all_tickets = fold acc = first_page.items for page_items in remaining_items {
    return acc + page_items
}

# Step 2: Fetch full details for every open ticket (for body and created_at)
detailed = for ticket in all_tickets {
    detail = get_ticket({ id: ticket.id })
    return detail
}

# Step 3: Determine cutoff: 7 days before 2026-06-10 = 2026-06-03
# Parse cutoff as epoch ms
cutoff = time.parse("2026-06-03T00:00:00Z")

# Step 4: Filter for tickets created before cutoff AND body mentions "refund"
# Then update each
escalated = for d in detailed {
    created_ms = time.parse(d.created_at) if d.created_at != null else null
    skip if created_ms == null
    skip if created_ms >= cutoff
    skip if d.body == null
    skip if !("refund" in d.body)

    # Update: set priority high, add tag billing-escalation
    result = update_ticket({
        id: d.id,
        priority: "high",
        add_tags: ["billing-escalation"]
    })
    return d.id
}

return { escalated_ticket_ids: escalated }

